INSERT INTO "TourPackage" (title, slug, description, destinationId, price, durationDays, maxPeople, featuredImage, gallery, includes, excludes, isFeatured, updatedAt) 
VALUES 
('K2 Base Camp Expedition', 'k2-base-camp-expedition', 'A legendary 20-day trek to the base of the world''s second-highest peak. This journey takes you through the heart of the Karakoram, witnessing the Baltoro Glacier and the breathtaking Concordia.', 25, 250000.0, 20, 12, 'https://images.unsplash.com/photo-1591193680687-32dc1f91b65e?auto=format&fit=crop&q=80', '[]', '["Certified Mountain Guide", "All Camping Gear", "Porters for Personal Gear", "Domestic Flights (Skardu-Islamabad)", "All Meals"]', '["International Flights", "Personal Insurance", "Tips for Staff"]', 1, CURRENT_TIMESTAMP),

('Hunza Autumn Gold Tour', 'hunza-autumn-gold-tour', 'Experience the magical transformation of Hunza Valley as the apricot and cherry trees turn brilliant shades of gold and orange. Includes visits to Karimabad, Altit and Baltit Forts, and Hussaini Suspension Bridge.', 27, 65000.0, 7, 10, 'https://images.unsplash.com/photo-1589982840479-799480922878?auto=format&fit=crop&q=80', '[]', '["Luxury Accommodation", "Private 4x4 Transport", "Entry Fees to Forts", "English Speaking Guide", "Kashmiri Tea Sessions"]', '["Lunches", "Personal Shopping", "Boating Fees at Attabad Lake"]', 1, CURRENT_TIMESTAMP),

('Swat Valley Discovery', 'swat-valley-discovery', 'Explore the "Switzerland of the East." This 4-day trip covers Malam Jabba, Kalam, and the Ushu Forest. Perfect for families and nature lovers seeking alpine meadows and rushing rivers.', 16, 35000.0, 4, 15, 'https://images.unsplash.com/photo-1627894460591-7649ccf4544d?auto=format&fit=crop&q=80', '[]', '["3-star Hotel Stay", "Dedicated Driver", "Traditional Pashtun BBQ Dinner", "Photography Support"]', '["Skiing Equipment Rental", "Personal Snacks"]', 0, CURRENT_TIMESTAMP),

('Naran-Kaghan High Meadows', 'naran-kaghan-high-meadows', 'A classic north-bound circuit featuring Lake Saif-ul-Malook, Lulusar Lake, and Babusar Top. Experience the lush green valleys and the crystal clear waters of the Kunhar River.', 19, 48000.0, 5, 12, 'https://images.unsplash.com/photo-1549445100-3443e248b1aa?auto=format&fit=crop&q=80', '[]', '["Transport by Jeep/Hiace", "Hotel Accommodation", "Breakfast", "Guided Hike to Ansoo Lake"]', '["Dinner", "Horse Riding Fees"]', 1, CURRENT_TIMESTAMP),

('Lahore Food & Heritage Tour', 'lahore-food-heritage-tour', 'Immerse yourself in the cultural capital of Pakistan. A 2-day deep dive into the Walled City (Androon Shehar), the Badshahi Mosque, and the legendary food streets of Gawalmandi.', 2, 15000.0, 2, 20, 'https://images.unsplash.com/photo-1622659982722-fbc9246607bd?auto=format&fit=crop&q=80', '[]', '["Walled City Heritage Guide", "Street Food Tasting Menu", "Badshahi Mosque Entry", "Rickshaw Rides"]', '["Heavy Souvenir Shopping", "Hotel Stay"]', 0, CURRENT_TIMESTAMP),

('Murree Snow Weekend', 'murree-snow-weekend', 'A perfect quick getaway from Islamabad. Enjoy the snowfall, the scenic chairlifts of Patriata, and the cozy vibes of the Mall Road. Ideal for a refreshing weekend break.', 5, 22000.0, 3, 8, 'https://images.unsplash.com/photo-1596464716127-f2a82984de30?auto=format&fit=crop&q=80', '[]', '["Cozy Guesthouse Stay", "Round-trip Transport from Islamabad", "Mall Road Walking Tour", "Chairman Lift Fees"]', '["Ski/Snowboard Rental", "Extra Heaters in Room"]', 0, CURRENT_TIMESTAMP),

('Karachi Mangrove & Beach Retreat', 'karachi-mangrove-beach-retreat', 'Discover the hidden coastal gems of Karachi. Ride through the lush Mangroves of Kemari and spend a night at a luxury hut in Turtle Beach. Seafood dinner included.', 10, 18500.0, 2, 10, 'https://images.unsplash.com/photo-1540339832862-4745aa61b936?auto=format&fit=crop&q=80', '[]', '["Private Hut at Turtle Beach", "Yacht/Boat Ride through Mangroves", "Fresh Seafood Platter", "Security Support"]', '["Personal Parasailing Fees", "Deep Sea Fishing Gear"]', 0, CURRENT_TIMESTAMP),

('Mohenjo-Daro Legacy Tour', 'mohenjo-daro-legacy-tour', 'Step back 5,000 years into the Indus Valley Civilization. A 3-day expert-led tour of the Mohenjo-Daro ruins, the museum, and the nearby Kot Diji Fort. Essential for history buffs.', 14, 42000.0, 3, 10, 'https://images.unsplash.com/photo-1596395819057-e37f55a8516d?auto=format&fit=crop&q=80', '[]', '["Archeology Special Guide", "Airport Transfers (Sukkur/Larkana)", "Hotel in Sukkur", "Museum Entry Fees"]', '["Personal Porter for Luggage", "Extra Beverages"]', 0, CURRENT_TIMESTAMP),

('Chitral Kalash Valley Discovery', 'chitral-kalash-valley-discovery', 'Visit the unique Kalash people in their secluded valleys. Learn about their ancient polytheistic traditions, witness the local dancing, and enjoy the pristine beauty of the Hindu Kush.', 17, 75000.0, 6, 8, 'https://images.unsplash.com/photo-1527845649931-e8d9101ae0ca?auto=format&fit=crop&q=80', '[]', '["Traditional Kalash Homestay", "Private 4x4 Jeep", "Kalasha Cultural Workshop", "All Meals", "Donation to Community Fund"]', '["Personal Souvenirs (Kalash Hats/Robes)", "Alcoholic Beverages"]', 1, CURRENT_TIMESTAMP),

('Islamabad Urban Insights', 'islamabad-urban-insights', 'A modern look at the capital. Hike Trial 3 or 5, visit the Faisal Mosque, and enjoy dinner at Monal with panoramic views of the city. Perfect for transit travelers.', 4, 12000.0, 2, 15, 'https://images.unsplash.com/photo-1533154101036-70228d45140e?auto=format&fit=crop&q=80', '[]', '["Hiking Guide", "Faisal Mosque Access", "Monal Dinner Reservation (Fixed Menu)", "City Tour Transport"]', '["Hotel Stay", "Private Shopping Transfers"]', 0, CURRENT_TIMESTAMP);
